INSERT INTO feature VALUES('naturality','identity','Naturality along a path','math-path','implemented','notable',NULL,'A term''s naturality along a path in one of its arguments is the term''s action on that path: `natural` in `std.math.path`, a homotopy''s naturality along a path, is the operation at one variable, by based path induction on the path. Example 1.3 of Benjamin et al. 2025, the associator''s naturality in its first argument, states the square Catt answers for `assoc [a] g h`, its source the associator at the path''s start then the path whiskered by `Path.step(g, h)`, its target the path whiskered by `g` and then by `h` then the associator at its end; its term is `natural` at the associator, its target side carried along `apComp` to the two whiskers, and the kernel replays it. `natassoc` writes the same naturality as the filler generator over the 3-chain, and `natassocAgrees` relates the two terms at every path by based path induction, since two inductions on a variable path do not convert. The filler generator `fill` is the operation at a set `X` of cells and vertices: Examples 1.1 to 1.3, the composite''s naturality in a cell and in its whole context and the associator''s in all three cells, check there at the types Catt answers.',NULL,'corpus/ledger/features/naturality.gandr','corpus/ledger/features/naturality.gandr',NULL);
